@Injectable({ providedIn: 'root' })
export class TranslationService {
  private readonly document = inject(DOCUMENT);
  private readonly isBrowser = isPlatformBrowser(inject(PLATFORM_ID));
  private readonly currentLocale = signal<AppLocale>('fa');

  readonly locale = this.currentLocale.asReadonly();
  readonly direction = computed(() => this.locale() === 'fa' || this.locale() === 'ar' ? 'rtl' : 'ltr');
  readonly languageOptions = languages;
  readonly selectedLanguage = computed(() => languages.find(language => language.code === this.locale())!);

  constructor() {
    this.applyDocumentLanguage();
    if (this.isBrowser) {
      afterNextRender(() => {
        const savedLocale = this.readSavedLocale();
        if (savedLocale !== this.locale()) this.setLanguage(savedLocale);
      });
    }
  }

  setLanguage(locale: AppLocale): void {
    this.currentLocale.set(locale);
    if (this.isBrowser) {
      try { localStorage.setItem('fara-sanat-language', locale); } catch { /* Storage may be disabled. */ }
    }
    this.applyDocumentLanguage();
  }

  translate(value: string | null | undefined): string {
    if (!value) return value ?? '';
    const locale = this.locale();
    if (locale === 'fa') return value;
    const key = value.replace(/\s+/g, ' ').trim();
    const productTranslation = productTranslations[key];
    const translated = productTranslation
      ? productTranslation[locale === 'en' ? 0 : locale === 'ar' ? 1 : 2]
      : translations[locale][key] ?? value;
    return this.localizeDigits(translated);
  }

  translateHomeProduct(id: string, sourceName: string): string {
    return homeProductNames[id]?.[this.locale()] ?? this.translate(sourceName);
  }

  localizeDigits(value: string): string {
    const arabicIndicDigits = '٠١٢٣٤٥٦٧٨٩';
    const persianDigits = '۰۱۲۳۴۵۶۷۸۹';
    return value.replace(/[0-9۰-۹٠-٩]/g, digit => {
      const code = digit.charCodeAt(0);
      const index = code >= 0x06f0 && code <= 0x06f9
        ? code - 0x06f0
        : code >= 0x0660 && code <= 0x0669
          ? code - 0x0660
          : Number(digit);
      if (this.locale() === 'fa') return persianDigits[index];
      if (this.locale() === 'ar') return arabicIndicDigits[index];
      return String(index);
    });
  }

  private readSavedLocale(): AppLocale {
    if (!this.isBrowser) return 'fa';
    try {
      const saved = localStorage.getItem('fara-sanat-language');
      if (saved === 'en' || saved === 'ar' || saved === 'zh' || saved === 'fa') return saved;
    } catch { /* Storage may be disabled. */ }
    return 'fa';
  }

  private applyDocumentLanguage(): void {
    const locale = this.locale();
    this.document.documentElement.lang = locale;
    this.document.documentElement.style.setProperty('--localized-text-direction', this.direction());
    this.document.title = {
      fa: 'گروه صنعتی فراصنعت ایران',
      en: 'Fara Sanat Iran Industrial Group',
      ar: 'مجموعة فرا صنعت إيران الصناعية',
      zh: '法拉工业集团',
    }[locale];
  }
}
